DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]


def _is_leap(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)


def _leap_days_before(y):
    """Number of leap years in [1, y - 1] of the proleptic Gregorian calendar."""
    y -= 1
    return y // 4 - y // 100 + y // 400


def _ordinal(s):
    y, m, d = map(int, s.split('-'))
    leap_day = 1 if m > 2 and _is_leap(y) else 0
    return y * 365 + _leap_days_before(y) + sum(DAYS[: m - 1]) + leap_day + d


def days_between(a, b):
    return _ordinal(b) - _ordinal(a)
